CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS restaurants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, phone TEXT, tax_rate_bps INTEGER NOT NULL DEFAULT 0 CHECK (tax_rate_bps BETWEEN 0 AND 10000), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS menu_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id UUID NOT NULL REFERENCES restaurants(id), name TEXT NOT NULL, category TEXT NOT NULL, description TEXT, price_cents INTEGER NOT NULL CHECK (price_cents >= 0), is_available BOOLEAN NOT NULL DEFAULT TRUE, stock_qty INTEGER CHECK (stock_qty >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS calls (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id UUID NOT NULL REFERENCES restaurants(id), twilio_call_sid TEXT NOT NULL UNIQUE, caller_phone TEXT, status TEXT NOT NULL DEFAULT 'active', started_at TIMESTAMPTZ NOT NULL DEFAULT now(), ended_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id UUID NOT NULL REFERENCES restaurants(id), call_id UUID UNIQUE REFERENCES calls(id), customer_name TEXT, customer_phone TEXT, status TEXT NOT NULL DEFAULT 'confirmed', payment_method TEXT NOT NULL CHECK (payment_method IN ('cash','stripe')), payment_status TEXT NOT NULL DEFAULT 'unpaid', subtotal_cents INTEGER NOT NULL CHECK (subtotal_cents >= 0), tax_cents INTEGER NOT NULL CHECK (tax_cents >= 0), total_cents INTEGER NOT NULL CHECK (total_cents >= 0), stock_reserved BOOLEAN NOT NULL DEFAULT FALSE, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), confirmed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, menu_item_id UUID NOT NULL REFERENCES menu_items(id), item_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0), line_total_cents INTEGER NOT NULL CHECK (line_total_cents >= 0), substituted_for TEXT, substitution_approved BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL UNIQUE REFERENCES orders(id), stripe_session_id TEXT UNIQUE, checkout_url TEXT, amount_cents INTEGER NOT NULL CHECK (amount_cents >= 0), status TEXT NOT NULL DEFAULT 'pending', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_events (event_id TEXT PRIMARY KEY, provider TEXT NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now());
